Rinit.doc:
Raven
Lightweight, multithreaded, retained-mode GUI library in C.

raven_core.h : base types, lifecycle, main loop, threading, errors.

Conventions:
- every object is an opaque Rid handle, R_INVALID_ID on failure
- functions are R<object>_<action>: Rwindow_create, Rwindow_destroy,
Rwindow_is_valid, Rwindow_set_title, Rwindow_get_size...
- types are RName (RInitDesc, REvent, RKey), callbacks are RNameCallback,
constants and enum values are R_NAME
- booleans are ints (R_TRUE / R_FALSE), colors are float r, g, b, a
- strings are UTF-8 and always copied by the library

Threading: unless a function is documented as thread-safe, it must be
called from the UI thread (the thread that called Rinit).
/

#ifndef RAVEN_CORE_H
#define RAVEN_CORE_H

#define RAVEN_VERSION_MAJOR 0
#define RAVEN_VERSION_MINOR 2
#define RAVEN_VERSION_PATCH 3
#define RAVEN_API_VERSION "0.2"

#ifdef __cplusplus
#include <cstdint>
#include <cstddef>
#else
#include <stdint.h>
#include <stddef.h>
#endif


/** shared library export / import */

#if defined(_WIN32)
#if defined(RAVEN_BUILD_DLL)
#define RAVEN_API __declspec(dllexport)
#elif defined(RAVEN_USE_DLL)
#define RAVEN_API __declspec(dllimport)
#else
#define RAVEN_API
#endif
#elif defined(__GNUC__) && defined(RAVEN_BUILD_DLL)
#define RAVEN_API __attribute__((visibility("default")))
#else
#define RAVEN_API
#endif


/**
Opaque handle to any Raven object (window, widget, font, texture, timer,
tree item). A handle carries the object type and a generation counter, so
using a deleted handle is detected and reported instead of crashing.
Both R_INVALID_ID and 0 are never valid handles.
/
typedef uint32_t Rid;
typedef uint32_t Ruint;

#define R_FALSE ((int)0)
#define R_TRUE  ((int)1)

#define R_INVALID_ID ((Rid)-1)


typedef enum RBackend{
/** Built-in Vulkan renderer. */
R_BACKEND_VULKAN = 0x0001,
/** Renders nothing. Used for headless runs and unit tests. */
R_BACKEND_NULL,
/** Backend supplied with Rbackend_register (see raven_backend.h). */
R_BACKEND_CUSTOM,
/** Browser renderer (Emscripten, WebGL 2). */
R_BACKEND_WEBGL
}RBackend;

typedef enum RError{
R_NO_ERROR = 0x0070,
R_ERROR_INVALID_ID,
R_ERROR_INVALID_ENUM,
R_ERROR_INVALID_VALUE,
R_ERROR_INVALID_OPERATION,
R_ERROR_BACKEND,
R_ERROR_PLATFORM,
R_ERROR_OUT_OF_MEMORY,
R_ERROR_INVALID_FILE_FORMAT,
R_ERROR_FILE_NOT_FOUND,
R_ERROR_XML,
R_ERROR_WRONG_THREAD
}RError;

typedef enum RSeverity{
R_SEVERITY_WEAK_WARNING = 0x0080,
R_SEVERITY_WARNING,
R_SEVERITY_ERROR,
R_SEVERITY_FATAL
}RSeverity;


/**
Optional settings for Rinit_ex. A zero-initialized structure selects the
default for every field, so new fields can be added without breaking code.
/
typedef struct RInitDesc {
/** Rendering backend. 0 selects WebGL in browser builds, Vulkan otherwise. */
RBackend backend;
/** Application name reported to the graphics driver. May be NULL. */
const char* app_name;
/** Worker threads of the job system. 0 = one per spare CPU core, negative = none. */
int worker_threads;
/** R_TRUE renders on the UI thread instead of a dedicated render thread. */
int disable_render_thread;
/** R_TRUE presents without waiting for the vertical blank. */
int disable_vsync;
/** R_TRUE enables the backend debug layer (Vulkan validation) when installed. */
int enable_validation;
/** R_TRUE opens no OS window (null platform). Combine with R_BACKEND_NULL for tests. */
int headless;
/** Global UI scale multiplier applied on top of the monitor scale. 0 = 1.0. */
float ui_scale;
} RInitDesc;

/** Memory functions of the application, to replace the allocator of Raven. See Rset_allocator. */
typedef struct RAllocator {
void* (*alloc)(size_t size, void* user_data);
void* (*realloc)(void* ptr, size_t size, void* user_data);
void  (*free)(void* ptr, void* user_data);
void* user_data;
} RAllocator;

/** What the library holds. See Rmemory_get_stats. */
typedef struct RMemoryStats {
/** Bytes in the blocks currently allocated. 0 with the allocator of the application. */
size_t used_bytes;
/** Highest value of used_bytes since the start. */
size_t peak_bytes;
/** Bytes taken from the OS: used_bytes, plus what is free in the heap. */
size_t reserved_bytes;
/** Blocks currently allocated. 0 after Rshutdown: anything else is a leak of the library. */
size_t allocation_count;
/** Allocations made since the start. */
uint64_t total_allocations;
} RMemoryStats;

/** Timings and counters of the last frame produced for a window. */
typedef struct RFrameStats {
double layout_ms;
double paint_ms;
double render_ms;
Ruint widget_count;
Ruint instance_count;
Ruint draw_call_count;
/** Glass: times the frame was copied and blurred to be seen through (0 without glass). */
Ruint backdrop_count;
Ruint paint_job_count;
uint64_t frame_index;
} RFrameStats;


#ifdef __cplusplus
extern "C" {
#endif

/* ============================================================================
INITIALIZATION & LIFECYCLE
============================================================================ */

/**
Starts the library with default settings on the given backend.
The calling thread becomes the UI thread.
Returns R_TRUE on success. On failure, see Rerror_get_last.

Rdraw_frame.doc:
Raven has no loop of its own: the application writes it and asks for one
frame at a time.

while (Rdraw_frame()) {            a game or an engine: never waits,
update_and_render_my_scene();  call it once per frame of yours
}

while (Rwait_frame(-1.0)) {        a tool: sleeps until something
}                                  happens, costs nothing when idle

return Rget_exit_code();
/

/**
Produces one frame: processes the pending OS events without
waiting, runs the posted tasks and the timers, then lays out, paints and
submits every window that changed. A window in which nothing changed is
not drawn again, so the call is cheap when the UI is idle.
Returns R_FALSE once Rquit was called or the last window is closed.

Rget_delta_time.doc:
Registers a function called once per frame, before the layout.
The body of your loop does the same job; the callback is also called
while the OS keeps the thread in a loop of its own (on Windows, while
the user moves or resizes a window), when your loop is not running.
/
typedef void (*RFrameCallback)(double delta_seconds, void* user_data);
RAVEN_API void Rset_frame_callback(RFrameCallback callback, void* user_data);

/** return Seconds between the last two frames.

Rwindow_create.doc:
Raven
raven_window.h : OS windows, input enums and events.

Raven creates and owns its windows (Win32, X11, Cocoa on macOS). Sizes and positions are in
logical units; multiply by Rwindow_get_scale to get pixels.
/

#ifndef RAVEN_WINDOW_H
#define RAVEN_WINDOW_H

#include "raven_core.h"


typedef enum RWindowFlags{
R_WINDOW_DEFAULT    = 0,
R_WINDOW_NO_RESIZE  = (1 << 0),
R_WINDOW_HIDDEN     = (1 << 1),
R_WINDOW_BORDERLESS = (1 << 2),
R_WINDOW_MAXIMIZED  = (1 << 3),
/**
No title bar from the OS: the content covers the whole window and
draws its own header, with a R_WIDGET_HEADER_BAR (raven_shell.h) or
with any widget given to Rwidget_set_window_drag. The window is still
moved, resized, snapped and maximized by the OS, as it does for its own
title bars.
/
R_WINDOW_CUSTOM_HEADER = (1 << 4),
/**
The window can be seen through: where the application draws nothing
opaque, what is behind the window on the screen shows (the desktop,
the other applications), not a color of the application. Glass then
looks at the screen itself. What the OS does to what shows through is
chosen with Rwindow_set_backdrop. See RBackdrop for what each window
system can do.
/
R_WINDOW_TRANSPARENT = (1 << 5),
/**
A splash screen: shown while the application starts. No frame (it
implies R_WINDOW_BORDERLESS and R_WINDOW_NO_RESIZE, and cancels
R_WINDOW_MAXIMIZED and R_WINDOW_CUSTOM_HEADER), centered on the screen
before it is first shown and again when its size changes, above the
other windows, out of the taskbar and of Alt+Tab (Windows), of the
Window menu and of Cmd+` (macOS), typed _NET_WM_WINDOW_TYPE_SPLASH on
X11. Wayland gives it no place of its own: it is a window without frame
there. The application destroys it once its main window is ready
(creating the main window first keeps Ris_running true).
/
R_WINDOW_SPLASH_SCREEN = (1 << 6)
}RWindowFlags;

/** Where a window in picture in picture goes (Rwindow_set_picture_in_picture_layout). */
typedef enum RPictureInPictureCorner {
R_PIP_BOTTOM_RIGHT = 0x0780,
R_PIP_BOTTOM_LEFT,
R_PIP_TOP_RIGHT,
R_PIP_TOP_LEFT
} RPictureInPictureCorner;

/**
What is seen behind a window created with R_WINDOW_TRANSPARENT.

Windows 11          every value
Windows 10          TRANSPARENT, BLUR, ACRYLIC (MICA gives ACRYLIC)
macOS               TRANSPARENT; other backdrops fall back to transparency
X11                 TRANSPARENT with any compositing manager; BLUR where
the compositor blurs on request (KWin; picom and
others with their own settings); ACRYLIC and MICA
give BLUR
no compositor       nothing: the window stays opaque
/
typedef enum RBackdrop{
/** Opaque: the window color, or the wallpaper of the theme. */
R_BACKDROP_NONE = 0x0400,
/** The screen behind the window, as it is. */
R_BACKDROP_TRANSPARENT,
/** The screen behind the window, blurred by the OS. */
R_BACKDROP_BLUR,
/** Blurred, tinted and grained by the OS (the acrylic of Windows). */
R_BACKDROP_ACRYLIC,
/** A soft tint taken from the wallpaper of the desktop (the mica of Windows 11). */
R_BACKDROP_MICA
}RBackdrop;

typedef enum RWindowSystem{
R_WINDOW_SYSTEM_NONE = 0x0090,
R_WINDOW_SYSTEM_WIN32,
R_WINDOW_SYSTEM_X11,
R_WINDOW_SYSTEM_WAYLAND,
R_WINDOW_SYSTEM_COCOA,
R_WINDOW_SYSTEM_EMSCRIPTEN,
R_WINDOW_SYSTEM_ANDROID,
R_WINDOW_SYSTEM_UIKIT
}RWindowSystem;

/** Distances from the edges of a window, in logical units. */
typedef struct RInsets {
float top, right, bottom, left;
} RInsets;

/** The on-screen keyboard appeared, changed height or went away: `height` in logical units, 0 when hidden. */
typedef void (*RKeyboardCallback)(Rid window, int visible, float height, void* user_data);

/** What a text input holds: on mobile it picks the on-screen keyboard (letters, @, digits...). */
typedef enum RTextInputType {
R_TEXT_INPUT_TYPE_TEXT = 0x0B60,
R_TEXT_INPUT_TYPE_EMAIL,
R_TEXT_INPUT_TYPE_NUMBER,
/** Digits and a decimal separator. */
R_TEXT_INPUT_TYPE_DECIMAL,
R_TEXT_INPUT_TYPE_PHONE,
R_TEXT_INPUT_TYPE_URL,
R_TEXT_INPUT_TYPE_SEARCH
} RTextInputType;

/** The label and meaning of the return key of the on-screen keyboard. Enter does the same on every key. */
typedef enum RReturnKey {
R_RETURN_KEY_DEFAULT = 0x0B70,
R_RETURN_KEY_DONE,
R_RETURN_KEY_GO,
R_RETURN_KEY_NEXT,
R_RETURN_KEY_SEARCH,
R_RETURN_KEY_SEND
} RReturnKey;

/** What the platform needs to know of the focused text input to set up the on-screen keyboard. */
typedef struct RTextInputInfo {
RTextInputType type;
RReturnKey return_key;
/** R_TRUE: the text is hidden (no suggestions, no autocorrection, no learning). */
int password;
int read_only;
/** Most characters accepted; 0 for no limit. */
int max_length;
} RTextInputInfo;

/**
Native handles of a window or of a native viewport.
Win32 : display = HINSTANCE, window = HWND
X11   : display = Display*,  window = Window (XID), visual = VisualID
Wayland: display = wl_display*, window = wl_surface* (Linux and BSD choose
Wayland or X11 when Rinit runs: check `system`)
Cocoa : display = NSWindow*, window = CAMetalLayer* for Vulkan presentation
Emscripten: window = opaque browser surface token (no OS window handle)
Android: window = ANativeWindow*
UIKit : display = UIWindow*, window = CAMetalLayer* for Vulkan presentation (iOS, iPadOS)
/
typedef struct RNativeWindow {
RWindowSystem system;
void* display;
uintptr_t window;
uintptr_t visual;
/**
R_TRUE when the window was created with R_WINDOW_TRANSPARENT and the
window system gave it an alpha channel: what is presented in it must
carry alpha (premultiplied), which a rendering backend asks for when
it creates its surface.
/
int transparent;
} RNativeWindow;

/** Edges and corners of a window, for Rwindow_begin_resize. */
typedef enum RWindowEdge{
R_EDGE_LEFT = 0x00D0,
R_EDGE_RIGHT,
R_EDGE_TOP,
R_EDGE_BOTTOM,
R_EDGE_TOP_LEFT,
R_EDGE_TOP_RIGHT,
R_EDGE_BOTTOM_LEFT,
R_EDGE_BOTTOM_RIGHT
}RWindowEdge;

typedef enum RMouseButton{
R_MOUSE_LEFT = 0,
R_MOUSE_RIGHT,
R_MOUSE_MIDDLE,
R_MOUSE_X1,
R_MOUSE_X2
}RMouseButton;

typedef enum RModifier{
R_MOD_SHIFT = (1 << 0),
R_MOD_CTRL  = (1 << 1),
R_MOD_ALT   = (1 << 2),
R_MOD_SUPER = (1 << 3)
}RModifier;

typedef enum RCursor{
R_CURSOR_ARROW = 0x00B0,
R_CURSOR_IBEAM,
R_CURSOR_HAND,
R_CURSOR_CROSSHAIR,
R_CURSOR_RESIZE_H,
R_CURSOR_RESIZE_V,
R_CURSOR_RESIZE_NWSE,
R_CURSOR_RESIZE_NESW,
R_CURSOR_MOVE,
R_CURSOR_NOT_ALLOWED,
/** No pointer at all (a game that hides it). Windows; elsewhere the arrow. */
R_CURSOR_NONE
}RCursor;

